INSERT INTO `document` (
    document_code, workspace_id, parent_id, owner_user_id, title, file_name, document_type, status, current_version_no, index_input_revision,
    idempotency_key, deleted_at, created_at, updated_at
) VALUES (
    #{documentCode}, #{workspaceId}, #{parentId}, #{ownerUserId}, #{title}, #{fileName}, #{documentType}, #{status}, #{currentVersionNo}, #{indexInputRevision},
    #{idempotencyKey}, #{deletedAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE `document`
SET status = #{status},
    current_version_no = #{currentVersionNo},
    index_input_revision = #{indexInputRevision},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND index_input_revision = #{expectedIndexInputRevision}
  AND ((#{expectedVersionNo} = 0 AND current_version_no IS NULL) OR current_version_no = #{expectedVersionNo})
  AND status IN (0, 1)

UPDATE `document`
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND index_input_revision = #{expectedIndexInputRevision}
  AND current_version_no = #{expectedVersionNo}
  AND status = 2

UPDATE `document`
SET title = #{title},
    file_name = #{fileName},
    index_input_revision = #{indexInputRevision},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND index_input_revision = #{expectedIndexInputRevision}
  AND status = 2

mapper.select:
SELECT id, document_code, workspace_id, parent_id, owner_user_id, title, file_name, document_type, status, current_version_no, index_input_revision,
       idempotency_key, deleted_at, created_at, updated_at
FROM `document`
WHERE workspace_id = #{workspaceId}
  AND owner_user_id = #{ownerUserId}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1
